import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

const PAGE_SIZE = 10;

export type User = {
  id: string;
  name: string;
  role: string;
  active: boolean;
};

type UsersTableProps = {
  users: User[];
};

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <div className="jx-stack">
      <table className="jx-table">
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} className="jx-text jx-text--muted">
                Нет пользователей
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id}>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>
                  <span
                    className={
                      user.active
                        ? 'jx-badge jx-badge--success'
                        : 'jx-badge jx-badge--neutral'
                    }
                  >
                    {user.active ? 'Активен' : 'Отключён'}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Навигация по страницам"
        style={{ gap: 'var(--jx-space-2)' }}
      >
        <JxButton
          variant="secondary"
          disabled={currentPage <= 1}
          onClick={() => setPage(currentPage - 1)}
        >
          Назад
        </JxButton>
        <span className="jx-text jx-text--muted" aria-live="polite">
          Страница {currentPage} из {pageCount}
        </span>
        <JxButton
          variant="secondary"
          disabled={currentPage >= pageCount}
          onClick={() => setPage(currentPage + 1)}
        >
          Вперёд
        </JxButton>
      </nav>
    </div>
  );
}

export default UsersTable;

